/// <summary>
/// CB521_ExciseRegister
/// Controller class for excise lodgment update
/// </summary>
class METExciseLodgementUpdateController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Construct method
/// </summary>
/// <param name = "_executionMode">Execution mode reference</param>
/// <returns>METExciseLodgementUpdateController</returns>
public static METExciseLodgementUpdateController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METExciseLodgementUpdateController controller = new METExciseLodgementUpdateController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

/// <summary>
/// New method to initate service process
/// </summary>
protected void new()
{
    super(classStr(METExciseLodgementUpdateService),
        methodStr(METExciseLodgementUpdateService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Main method for controller class
/// </summary>
/// <param name = "_args">Args reference</param>
public static void main(Args _args)
{
    METExciseLodgementUpdateController  metExciseILodgementUpdateController = METExciseLodgementUpdateController::construct();
    metExciseILodgementUpdateController.parmArgs(_args);
    metExciseILodgementUpdateController.startOperation();
}
